<script setup lang="ts">
import {ref,nextTick} from 'vue'
const visible=ref(true),restore=ref<HTMLButtonElement>(),dialog=ref<HTMLDialogElement>(),opener=ref<HTMLButtonElement>()
function dismiss(){visible.value=false;nextTick(()=>restore.value?.focus())}
function open(){dialog.value?.showModal()}
function closed(){opener.value?.focus()}
</script>
<template><section class="close-button-usage" aria-label="Close button demonstration"><p>Fictitious local panel and native dialog. Closing does not delete data or save changes.</p><div class="actions"><button ref="restore" type="button" @click="visible=true">Restore sample panel</button><button ref="opener" type="button" @click="open">Open sample dialog</button></div><article v-if="visible" class="panel"><div><h3>Sample optional panel</h3><p>This is secondary detail that can be dismissed.</p></div><button type="button" class="close" aria-label="Dismiss sample optional panel" @click="dismiss"><span aria-hidden="true">×</span></button></article><p v-else role="status">Sample panel dismissed. Restore it above.</p><p>Disabled specimen: <button type="button" class="close" disabled aria-label="Close unavailable sample"><span aria-hidden="true">×</span></button></p><dialog ref="dialog" aria-labelledby="close-guide-dialog-title" @close="closed"><div class="dialog-header"><h3 id="close-guide-dialog-title">Sample dialog</h3><button type="button" class="close" aria-label="Close sample dialog" @click="dialog?.close()"><span aria-hidden="true">×</span></button></div><p>This native dialog also closes with Escape. Focus returns to its opener.</p></dialog></section></template>
