.close-button-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}button{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.close{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:8px;font-size:23px;line-height:1;transition:background 140ms ease-out,transform 120ms ease-out;flex-shrink:0}.close:hover:not(:disabled){background:var(--vp-c-brand-soft)}.close:active:not(:disabled){transform:scale(.96)}.close:disabled{opacity:.5}.panel,.dialog-header{display:flex;justify-content:space-between;align-items:start;gap:16px}.panel{padding:16px;border:1px solid var(--vp-c-divider);border-radius:8px;animation:close-panel 160ms ease-out}.panel h3,.dialog-header h3{margin:0}.panel p{margin-bottom:0}dialog{position:fixed;inset:0;margin:auto;width:min(440px,calc(100vw - 32px));padding:24px;border:1px solid var(--vp-c-divider);border-radius:12px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}dialog[open]{animation:close-panel 160ms ease-out}dialog::backdrop{background:#0008}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@keyframes close-panel{from{opacity:.4;translate:0 4px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){.close{transition:none}.panel,dialog[open]{animation:none}}
